macro_rules! deps {
    () => {
        Throughput!();
        WallTime!();
        Measurement!();
    };
}

macro_rules! ValueFormatter {
    () => {
        deps!();
        # [doc = " Trait providing functions to format measured values to string so that they can be displayed on"] # [doc = " the command line or in the reports. The functions of this trait take measured values in f64"] # [doc = " form; implementors can assume that the values are of the same scale as those produced by the"] # [doc = " associated [`Measurement`] (eg. if your measurement produces values in nanoseconds, the"] # [doc = " values passed to the formatter will be in nanoseconds)."] # [doc = ""] # [doc = " Implementors are encouraged to format the values in a way that is intuitive for humans and"] # [doc = " uses the SI prefix system. For example, the format used by [`WallTime`] can display the value"] # [doc = " in units ranging from picoseconds to seconds depending on the magnitude of the elapsed time"] # [doc = " in nanoseconds."] pub trait ValueFormatter { # [doc = " Format the value (with appropriate unit) and return it as a string."] fn format_value (& self , value : f64) -> String { let mut values = [value] ; let unit = self . scale_values (value , & mut values) ; format ! ("{:>6} {}" , short (values [0]) , unit) } # [doc = " Format the value as a throughput measurement. The value represents the measurement value;"] # [doc = " the implementor will have to calculate bytes per second, iterations per cycle, etc."] fn format_throughput (& self , throughput : & Throughput , value : f64) -> String { let mut values = [value] ; let unit = self . scale_throughputs (value , throughput , & mut values) ; format ! ("{:>6} {}" , short (values [0]) , unit) } # [doc = " Scale the given values to some appropriate unit and return the unit string."] # [doc = ""] # [doc = " The given typical value should be used to choose the unit. This function may be called"] # [doc = " multiple times with different datasets; the typical value will remain the same to ensure"] # [doc = " that the units remain consistent within a graph. The typical value will not be NaN."] # [doc = " Values will not contain NaN as input, and the transformed values must not contain NaN."] fn scale_values (& self , typical_value : f64 , values : & mut [f64]) -> & 'static str ; # [doc = " Convert the given measured values into throughput numbers based on the given throughput"] # [doc = " value, scale them to some appropriate unit, and return the unit string."] # [doc = ""] # [doc = " The given typical value should be used to choose the unit. This function may be called"] # [doc = " multiple times with different datasets; the typical value will remain the same to ensure"] # [doc = " that the units remain consistent within a graph. The typical value will not be NaN."] # [doc = " Values will not contain NaN as input, and the transformed values must not contain NaN."] fn scale_throughputs (& self , typical_value : f64 , throughput : & Throughput , values : & mut [f64] ,) -> & 'static str ; # [doc = " Scale the values and return a unit string designed for machines."] # [doc = ""] # [doc = " For example, this is used for the CSV file output. Implementations should modify the given"] # [doc = " values slice to apply the desired scaling (if any) and return a string representing the unit"] # [doc = " the modified values are in."] fn scale_for_machines (& self , values : & mut [f64]) -> & 'static str ; }
    };
}

ValueFormatter!()